arguments.command:
python - <<'PY'
try:
 import pymatgen; print('pymatgen',pymatgen.__version__)
except Exception as e: print('no pymatgen',e)
for m in ['matminer','sklearn','ase','xgboost','lightgbm','catboost']:
 try:
  x=__import__(m); print(m,getattr(x,'__version__','ok'))
 except Exception as e: print('no',m)
PY

python - <<'PY'
# test relevant imports
mods=['pymatgen.core','pymatgen.core.structure','pymatgen.symmetry.analyzer','pymatgen.analysis.local_env','mendeleev','periodictable','dscribe']
for m in mods:
 try:
  x=__import__(m,fromlist=['*']);print('yes',m)
 except Exception as e:print('no',m,str(e)[:100])
PY

