python - <<'PY'
from pymatgen.core import Element
x=Element('Si')
for a in dir(x):
 if not a.startswith('_'):
  try:
   v=getattr(x,a)
   if isinstance(v,(int,float,str)) or v is None: print(a,repr(v))
  except: pass
PY

